    category: "SQL",
    topic: "שאילתות מורכבות",
    difficulty: "intermediate",
    question: "איך היית בונה שאילתה שמציגה מכירות לפי חודש?",
    shortAnswer:
      "חולצים את החודש מתאריך המכירה עם DATE_TRUNC או MONTH(), מקבצים לפי חודש, ומחשבים סכום.",
    simpleExplanation:
      "שלב 1: MONTH(sale_date) — חלץ את מספר החודש מכל תאריך.\nשלב 2: GROUP BY MONTH(sale_date) — קבץ לפי חודש.\nשלב 3: SUM(amount) — חשב סכום לכל חודש.\nשלב 4: ORDER BY month — הצג כרונולוגית.\nב-PostgreSQL: DATE_TRUNC('month', sale_date) עדיף על MONTH().",
