    question: "איך שרת צריך להגיב אם משהו נכשל?",
    shortAnswer:
      "להחזיר קוד HTTP מתאים (4xx לשגיאת לקוח, 5xx לשגיאת שרת) עם הודעה ברורה. לא לחשוף פרטים טכניים רגישים.",
    simpleExplanation:
      "קוד HTTP נכון: 400 לקלט שגוי, 404 לא נמצא, 401/403 לאבטחה, 500 לשגיאת שרת.\nהגוף: JSON עם הסבר — { error: 'User not found', code: 'USER_NOT_FOUND' }.\nלא לחשוף: stack traces, שמות טבלאות, גרסאות ספריות — מידע שעוזר לתוקפים.\nLoggers: כל שגיאה נכתבת ל-log פנימי — לא לממשק הלקוח.\nFail gracefully: אפילו אם מסד הנתונים קרס, להחזיר 503 ולא להישאר תקוע.",
    example:
      "משתמש לא נמצא → 404 Not Found עם { error: 'User not found' }. שגיאה בDB → 500 Internal Server Error.",
