    shortAnswer: "TCP מבטיח שהמידע יגיע בצורה מלאה ובסדר הנכון, אבל איטי יותר. UDP מהיר יותר אבל לא מבטיח שהכל יגיע.",
    simpleExplanation: "TCP: connection-oriented — עושה handshake לפני שליחה, מאמת שכל packet הגיע, שולח מחדש אם לא.\nUDP: connectionless — שולח ולא מחכה. אם packet אבד — כלום.\nTCP מתאים ל: HTTP, HTTPS, אימייל, קבצים — כל מקום שדיוק חשוב.\nUDP מתאים ל: streaming, שיחות וידאו, gaming — עדיף frame אבוד מאשר lag.\nHTTP פועל מעל TCP. DNS פועל מעל UDP.",
    example: "TCP → גלישה באינטרנט, אימייל. UDP → שיחות וידאו, שידורי חי — עדיף שתמונה אחת תחסר מאשר הכל יתעכב.",
