    shortAnswer: "REST API הוא בקשה-תגובה חד-כיווני — הלקוח שואל, השרת עונה. WebSocket הוא חיבור מתמשך שמאפשר תקשורת דו-כיוונית.",
    simpleExplanation: "REST: כל בקשה היא independent. מתאים ל-CRUD, loading data, user actions.\nWebSocket: חיבור פתוח. מתאים לזמן אמת — שרת דוחף updates בלי שהלקוח ישאל.\nLong polling: פשרה — לקוח שואל כל כמה שניות. פחות יעיל מ-WebSocket.\nServerSent Events (SSE): שרת דוחף updates חד-כיווני — פשוט יותר מ-WebSocket.\nמסקנה: REST לרוב הדברים. WebSocket רק כשצריך real-time אמיתי.",
    example: "טעינת רשימת הזמנות → REST. עדכון סטטוס הזמנה בזמן אמת → WebSocket.",
