    question: "מה ההבדל בין latency לבין throughput?",
    shortAnswer: "Latency הוא הזמן שלוקח לבקשה אחת להגיע מנקודה לנקודה. Throughput הוא כמות הבקשות שהמערכת יכולה לטפל בשנייה.",
    simpleExplanation: "Latency = זמן תגובה לבקשה אחת: 50ms, 200ms, 1s. נמדד ב-ms.\nThroughput = כמות בקשות שמערכת מטפלת בשנייה (RPS — Requests per Second).\nלא תמיד קשורים: מערכת עם latency 1s יכולה לטפל ב-1000 RPS במקביל.\nאופטימיזציה: latency → caching, CDN, שיפור query. Throughput → horizontal scaling, load balancer.\nמדדים חשובים ל: p50 (חציון), p95, p99 latency — לא רק ממוצע.",
    example: "API עם latency נמוך (50ms לבקשה) אבל throughput נמוך (100 בקשות/שנייה) — מהיר לבקשה אחת, לא מתאים לעומסים גבוהים.",
    whatToMention: ["Latency = מהירות תגובה לבקשה בודדת", "Throughput = קיבולת טיפול כוללת", "שניהם חשובים, לא תמיד קשורים"],
