    simpleExplanation: "Same-Origin Policy: הדפדפן מונע מ-evil.com לשלוח בקשות ל-bank.com בשמך.\nCORS: שרת יכול לאשר לדומיינים ספציפיים לגשת אליו.\nAccess-Control-Allow-Origin: https://myapp.com — רק myapp.com מורשה.\nAccess-Control-Allow-Origin: * — כולם מורשים (מסוכן ב-production עם authentication).\nPreflight request: לפני בקשות מורכבות, הדפדפן שולח OPTIONS לבדוק הרשאות.",
