    shortAnswer: "שלושת עמודי התווך של אבטחת מידע: סודיות (רק מורשים ניגשים), שלמות (המידע לא שונה ללא אישור), זמינות (המידע נגיש כשצריך).",
    simpleExplanation: "CIA Triad = 3 עמודי תווך: Confidentiality, Integrity, Availability.\nConfidentiality (סודיות): רק מורשים יכולים לגשת למידע — הצפנה, הרשאות.\nIntegrity (שלמות): המידע לא שונה ללא אישור — checksums, audit logs, signatures.\nAvailability (זמינות): המידע נגיש כשצריך — backup, redundancy, anti-DDoS.\nכל מתקפה פוגעת לפחות באחד: ransomware → availability. גניבת DB → confidentiality. שינוי לוגים → integrity.",
    example: "מתקפת מניעת שירות (DDoS) פוגעת ב-Availability. גניבת נתונים פוגעת ב-Confidentiality. שינוי לוגים פוגע ב-Integrity.",
