    question: "איך אפשר לזהות ניסיון פישינג?",
    shortAnswer: "פישינג מתחזה לגורם אמין. סימנים: כתובת שולח מזויפת, קישורים חשודים, לחץ לפעול מיידית, בקשה לסיסמה.",
    simpleExplanation: "פישינג = התחזות לגורם אמין כדי להוציא מידע רגיש כמו סיסמה או פרטי אשראי.\nסימנים: כתובת שולח מזויפת (paypa1.com), שגיאות כתיב, לחץ לפעול מיידית.\nסוגים: Email phishing, Spear phishing (מכוון לאדם ספציפי), Smishing (SMS), Vishing (טלפון).\nארגון לגיטימי לא יבקש סיסמה במייל — תמיד חשד.\nלרחף מעל קישור לפני לחיצה — URL האמיתי מופיע בסרגל הסטטוס.",
    example: "מייל מ'support@paypa1.com' (l → 1) שמבקש אישור סיסמה דחוף עם קישור לאתר דומה.",
    whatToMention: ["לבדוק כתובת שולח", "לרחף מעל קישור לפני לחיצה", "לא למסור סיסמאות במייל", "לדווח על חשד"],
    commonMistakes: ["ללחוץ על קישור כי ה-'חברה' מוכרת — תמיד לאמת את הכתובת"],
