    shortAnswer: "MFA דורש יותר מדרך אחת לאמת זהות. גם אם הסיסמה נגנבת, תוקף עדיין צריך גורם שני כמו קוד SMS או אפליקציית authenticator.",
    simpleExplanation: "MFA = Multi-Factor Authentication: צריך לפחות שני גורמים לאישור זהות.\nגורמים: Something you know (סיסמה), Something you have (טלפון), Something you are (ביומטרי).\nגם אם סיסמה נגנבה — בלי הגורם השני, תוקף לא יכול להיכנס.\nTOTP (Google Authenticator): קוד 6 ספרות שמתחלף כל 30 שניות, נוצר מקומית — בטוח מאינטרצפציה.\nSMS MFA חלש יותר: SIM swapping יכול לעקוף אותו.",
