    shortAnswer: "חיפוש כניסות כושלות, שינויים בהרשאות, גישה לנתונים רגישים, פעולות בשעות חריגות, ו-IP addresses חשודים.",
    simpleExplanation: "לוגים = תיעוד כרונולוגי של פעולות במערכת — מי עשה מה, מתי, ומאיפה.\nמה לחפש: כניסות כושלות (brute force), שינויי הרשאות, גישה לנתונים רגישים.\nמתי חריג: שעות לא רגילות, תדירות גבוהה מהרגיל, IP ממדינה לא צפויה.\nמה עוד: error codes חוזרים, פעולות חריגות של משתמשים ספציפיים.\nכלים: SIEM כמו Splunk / ELK מאפשרים חיפוש, קורלציה, והתראות אוטומטיות.",
