    topic: "Least Privilege",
    difficulty: "basic",
    question: "למה לא לתת לכל משתמש הרשאות מנהל?",
    shortAnswer: "הרשאות מנהל מאפשרות לבצע פעולות הרסניות. אם חשבון נפגע, נזק עם הרשאות מנהל הרבה יותר גדול.",
    simpleExplanation: "Least Privilege: כל משתמש ותהליך מקבל רק את ההרשאות המינימליות לתפקידו.\nמטרה: להגביל נזק אם חשבון נפגע או אם משתמש עושה טעות.\nדוגמה: קורא DB מקבל SELECT בלבד — לא DELETE, INSERT, DROP.\nב-cloud: IAM roles מצומצמות לכל service — לא כולם Admin.\nביקורת הרשאות תקופתית: הרשאות שלא בשימוש מסוכנות ויש להסיר.",
    example: "מפתח שצריך רק לקרוא DB מקבל גם הרשאת DELETE — אם הוא טועה בquery, יכול למחוק הכל.",
