    simpleExplanation: "SQL Injection: הכנסת קוד SQL לתוך שדה קלט כדי לשנות את הquery שנשלח לDB.\nדוגמה: שם משתמש ' OR '1'='1 → query מחזיר כל המשתמשים.\nהשפעה: קריאת נתונים, שינוי, מחיקה — עד RCE בהגדרות מסוימות.\nמניעה: Parameterized Queries / Prepared Statements — SQL נשלח בנפרד מהנתונים.\nORM (SQLAlchemy, Hibernate) מגן אוטומטית. Input sanitization לא מספיקה לבד.",
