    simpleExplanation: "Brute Force: ניסוי שיטתי של כל הצירופים האפשריים עד שמוצאים את הנכון.\nDictionary attack: ניסוי סיסמאות נפוצות ממסמך — מהיר יותר מBrute Force מלא.\nCredential stuffing: שימוש בסיסמאות דלופות מDB אחר — ממש נפוץ.\nמניעה: Rate limiting, Account lockout, CAPTCHA, MFA.\nסיסמה ארוכה ומורכבת חשובה: 8 תווים פשוטים = שניות לפריצה. 16 תווים אקראיים = שנים.",
