    shortAnswer: "Rate Limiting מגביל כמה בקשות משתמש יכול לשלוח בזמן נתון. זה מקשה על Brute Force ומתקפות DoS.",
    simpleExplanation: "Rate Limiting: הגבלת מספר הבקשות ב-time window (לדוגמה: 10 בקשות לדקה לפי IP).\nמגן מ: Brute Force, Credential Stuffing, DDoS בסיסי, API scraping.\nמימוש: לפי IP, לפי user account, או שניהם גם יחד.\nתגובה: 429 Too Many Requests עם Retry-After header.\nכלים: nginx rate limiting, API Gateway throttling, express-rate-limit.",
