    simpleExplanation: "Least Privilege: כל ישות (משתמש, service, process) מקבלת רק מה שנדרש לתפקידה.\nמטרה: לצמצם blast radius אם ישות נפגעת.\nדוגמאות: DB user → SELECT only. Lambda function → S3 GET only. Dev → no prod access.\nZero Trust משלים: גם ישות פנימית לא מקבלת אמון אוטומטי — מאמתים כל גישה.\nביקורת תקופתית: הרשאות שלא בשימוש הופכות לסיכון לאורך זמן — יש לבטל.",
