    shortAnswer: "מתעדים מה נראה, מכילים את האיום (מונעים התפשטות), מודיעים לגורמים הרלוונטיים, ומתחילים חקירה.",
    simpleExplanation: "Incident Response: תהליך מובנה לטיפול באירועי אבטחה.\nשלבים: Identify → Contain → Eradicate → Recover → Lessons Learned.\nContain קודם: לנתק, לחסום, לבודד — לפני שמנסים להבין הכל.\nתיעוד כל הדרך: מה זוהה, מתי, מה נעשה — לצורך forensics ודיווח לבכירים.\nלא למחוק ראיות: snapshot של מחשב נגוע לפני ניקוי — ראיות חשובות לחקירה.",
