    shortAnswer: "מצפינים מידע רגיש בDB, מגבילים גישה לפי תפקיד, לא שומרים מידע שלא צריך, ומוחקים מידע שפג תוקפו.",
    simpleExplanation: "PII = Personally Identifiable Information: שם, email, ת\"ז, מספר כרטיס אשראי.\nData Minimization: לאסוף ולשמור רק מה שבאמת נחוץ — פחות נתונים = פחות סיכון.\nהצפנת נתונים at rest: PII ב-DB מוצפן — גם אם DB נגנב, נתונים לא קריאים.\nגישה מינימלית לפי תפקיד: רק מי שזקוק ל-PII לצורך עבודתו יכול לגשת.\nלוגים ללא PII: שם משתמש ב-log → להחליף ב-user_id. לוגים = מאגר PII נוסף.",
