    question: "איזה דברים חשוב לבדוק כדי לכתוב קוד מאובטח יותר?",
    shortAnswer: "לאמת קלט משתמש, להשתמש בParameterized Queries, לא לחשוף מידע רגיש בשגיאות, לנהל הרשאות נכון ולהצפין מידע רגיש.",
    simpleExplanation: "Input Validation: לאמת כל קלט משתמש — גם בclient-side וגם בserver-side.\nParameterized Queries: SQL עם placeholders (?) — מונע SQL Injection.\nError Handling: לא לחשוף stack trace, שמות קבצים, או מבנה DB בהודעות שגיאה.\nSecrets Management: API keys לא ב-code. להשתמש ב-env variables / secrets manager.\nDependency updates: לעדכן libraries שוטפות — חולשות ידועות מנוצלות ב-gaps.",
    example: "טופס ל-email → לאמת שזה email תקני. שאילתת DB → parameterized. הודעת שגיאה → לא לחשוף stack trace למשתמש.",
