    simpleExplanation: "Account Takeover (ATO): תוקף משיג שליטה על חשבון של משתמש לגיטימי.\nשיטות נפוצות: Credential stuffing, phishing, brute force, MFA bypass.\nאינדיקטורים: IP/מדינה חדשה, device fingerprint חדש, שינוי email/סיסמה לאחר login.\nחקירה: correlation לוגים — login location + change event + פעילות חריגה לאחר מכן.\nמניעה: MFA, anomaly detection, notifications על שינויי account, breach monitoring.",
