    topic: "Detection vs Prevention",
    difficulty: "advanced",
    question: "מה ההבדל בין detection לבין prevention?",
    shortAnswer: "Prevention מונע את ההתקפה לפני שקורה. Detection מזהה שהתקפה מתרחשת או קרתה. שניהם חיוניים.",
    simpleExplanation: "Prevention: חוסם את האיום לפני שקורה — firewall, WAF, input validation, patching.\nDetection: מזהה שהיה/יש פריצה — לוגים, SIEM, EDR, anomaly detection.\nDefense in Depth: מניחים שאחת השכבות תיכשל — לכן מוסיפים שכבות.\nMTTD (Mean Time to Detect): ממוצע עולמי ~197 יום — מה שמראה שDetection קריטי.\nFast detection limits blast radius: גם אם נפרצים, זיהוי מהיר מצמצם נזק.",
