    shortAnswer: "Zero Trust אומר: לא לסמוך על אף אחד ואף מכשיר אוטומטית — גם מי שבתוך הרשת הארגונית. לאמת תמיד, לתת גישה מינימלית.",
    simpleExplanation: "Zero Trust: לא לסמוך אוטומטית על אף ישות — בתוך הרשת או מחוצה לה.\nעקרונות: Verify explicitly (אמת כל גישה), Least Privilege, Assume Breach.\nבניגוד לCastle-and-moat: מי שבVPN סמוך. Zero Trust: גם מי שבפנים — לאמת תמיד.\nמימוש: MFA, device health checks, micro-segmentation, conditional access.\nIdentity = ה-perimeter החדש: זהות היא הגבול, לא כתובת IP.",
