    topic: "False Positive Reduction",
    difficulty: "advanced",
    question: "איך אפשר להפחית False Positives במערכת ניטור?",
    shortAnswer: "כיוון חוקים לפי context ספציפי לארגון, הוספת whitelist לפעולות ידועות ותקינות, ושיפור מתמיד של חוקים לפי feedback.",
    simpleExplanation: "Alert Fatigue: כמות FP גבוהה → אנליסטים מפסיקים לשים לב → איומים אמיתיים מפוספסים.\nTuning: כיוון חוקים לפי context ספציפי לארגון — לא one-size-fits-all.\nWhitelist: פעולות ידועות ותקינות מוסיפים ל-allowlist כדי לא לצלצל עליהן.\nFeedback loop: SOC מדווח על FP → מהנדסי Detection מכוונים חוקים בהתאם.\nמדידה: Rate FP/FN שבועי — FP עולה → tuning. FN עולה → חוקים חלשים מדי.",
    example: "script שרץ כל יום ב-3 לפנות בוקר מייצר alert → מוסיפים whitelist → מפסיק להיות noise → אנליסטים מתפנים לאיומים אמיתיים.",
