    difficulty: "basic",
    question: "מה זה ארכיטקטורת מערכת?",
    shortAnswer: "ארכיטקטורת מערכת היא תוכנית שמגדירה מאילו רכיבים המערכת בנויה, איך הם מתקשרים ואיך הם מאורגנים.",
    simpleExplanation: "ארכיטקטורת מערכת: תוכנית ברמה הגבוהה שמגדירה מאילו רכיבים המערכת בנויה ואיך הם מתקשרים.\nרמות נפוצות: Data Layer (DB), Business Logic Layer (Server/API), Presentation Layer (UI).\nתיעוד: Diagrams, ERD, Sequence Diagrams — מסבירים איך רכיבים עובדים יחד.\nמטרות: תחזוקה, scalability, הפרדת אחריויות, עבודת צוות מסודרת.\nארכיטקטורה ≠ קוד: ארכיטקטורה היא ההחלטות הגדולות שקשה לשנות — חשוב לבחור נכון מראש.",
    example: "מערכת קניות: Browser → API Server → Database + External Payment Service.",
    whatToMention: ["רכיבים ותקשורת ביניהם", "ארגון ויחסים", "בסיס לקבלת החלטות טכניות"],
