    topic: "חלוקה לרכיבים",
    difficulty: "basic",
    question: "למה מחלקים מערכת לרכיבים?",
    shortAnswer: "חלוקה לרכיבים מקלה על תחזוקה, מאפשרת לצוותים לעבוד במקביל ומקלה על שינויים עתידיים.",
    simpleExplanation: "חלוקה לרכיבים = Modularity: כל רכיב מטפל בנושא אחד בלבד (Single Responsibility).\nיתרונות: שינוי ברכיב אחד לא משפיע על אחרים. צוותים עובדים במקביל.\nניתן להחליף: DB driver, payment provider, email service — ללא שינוי שאר המערכת.\nHigh cohesion, Low coupling: הרכיב חזק פנימה, חלש בתלות על אחרים — עיקרון מרכזי.\nחלוקה יתרה = over-engineering: לא צריך רכיב נפרד לכל פונקציה.",
