    shortAnswer: "מערכת scalable יכולה לטפל בעומסים גדולים יותר — יותר משתמשים, יותר בקשות — בלי לקרוס או להאט משמעותית.",
    simpleExplanation: "Scalability: יכולת המערכת לטפל בעומס גדול יותר ללא קריסה או האטה.\nHorizontal scaling: מוסיפים עוד שרתים זהים מאחורי load balancer.\nVertical scaling: משדרגים שרת קיים (יותר CPU/RAM) — יש גבול חומרה.\nStateless services מאפשרים horizontal scaling — כל שרת יכול לטפל בכל בקשה.\nAuto-scaling: cloud מוסיף/מסיר instances אוטומטית לפי עומס.",
