    shortAnswer: "קוד קריא, מחולק לפונקציות קטנות, עם שמות ברורים, ללא כפילויות ועם הפרדה ברורה בין אחריויות.",
    simpleExplanation: "Maintainability: כמה קל לשנות, לתקן, ולהרחיב קוד קיים בלי לשבור דברים.\nפונקציות קטנות עם אחריות אחת (Single Responsibility Principle).\nשמות ברורים: calculateTax(price) ברור יותר מ-doStuff(x).\nDRY (Don't Repeat Yourself): קוד כפול = שגיאה כפולה + תיקון כפול.\nSeparation of Concerns: SQL, Business Logic, UI — כל אחד בשכבה נפרדת.",
