    difficulty: "intermediate",
    question: "מה זה Cache ולמה משתמשים בו?",
    shortAnswer: "Cache שומר תוצאות של חישובים יקרים או בקשות איטיות כדי להחזיר אותן מהר בפעם הבאה, בלי לחזור למקור.",
    simpleExplanation: "Cache: שכבת זיכרון מהיר שמאחסנת תוצאות מחושבות להחזרה מהירה.\nCache Hit: מצאנו ב-cache → מחזירים מיד (< 1ms). Cache Miss: לא מצאנו → שולפים מ-DB.\nTTL (Time To Live): זמן שבו cache נחשב תקף — אחרי זה מתרענן אוטומטית.\nRedis: כלי cache פופולרי — key-value store בזיכרון, latency < 1ms.\nCache Invalidation: מתי ואיך לנקות cache כשנתון ב-DB השתנה — הבעיה הקשה.",
    example: "תוצאות חיפוש נפוצות נשמרות ב-Redis. בפעם הבאה — מחזירים מ-cache ב-1ms, לא DB-query שלוקח 200ms.",
    whatToMention: ["מהיר יותר מגישה לDB", "Redis נפוץ כcache", "cache invalidation = אחד הדברים הקשים"],
    commonMistakes: ["לשמור ב-cache נתונים דינמיים ללא TTL נכון — מחזירים נתונים ישנים"],
