    question: "איך אפשר לגרום למערכת להיות אמינה יותר?",
    shortAnswer: "כפל רכיבים קריטיים (redundancy), תכנון graceful degradation, ניטור ותגובה מהירה לתקלות, ובדיקות עומסים.",
    simpleExplanation: "Reliability: ביטחון שהמערכת עובדת כצפוי לאורך זמן — נמדד ב-uptime (99.9% = 8.7h downtime/year).\nRedundancy: כפל רכיבים קריטיים — שרתים, DB replicas, load balancers.\nHealth checks: בדיקה אוטומטית ש-service חי → alert/failover אם לא מגיב.\nGraceful Degradation: אם שירות נופל, המערכת עובדת חלקית ולא קורסת לגמרי.\nChaos Engineering: מכבים שרתים בכוונה בסביבה מבוקרת — לבדוק שהמערכת עמידה.",
    example: "DB primary + replica → אם primary נופל, replica ממשיך. Health checks → alert אוטומטי אם שרת לא מגיב.",
    whatToMention: ["Redundancy", "Health checks ואוטומציה", "Graceful degradation", "Failover"],
