    simpleExplanation: "Error Handling: ניהול מבוקר של מצבי כשל שיכולים לקרות בכל מערכת.\nתפוס ואל תפיל: שגיאה שלא נתפסת עלולה להפיל את כל ה-process.\nLog מפורט פנימה: error message מלא + stack trace → ב-logs פנימיים בלבד.\nהודעה גנרית החוצה: \"שגיאה פנימית\" → למשתמש. לא פרטים טכניים.\nHTTP codes: 400 = שגיאת לקוח, 500 = שגיאת שרת, 503 = Service Unavailable.",
