    whatToMention: ["לתפוס שגיאות ולא לתת לhן להפיל את השרת", "logging מפורט פנימי", "הודעה גנרית למשתמש"],
    commonMistakes: ["להחזיר stack trace למשתמש — מידע רגיש שמסייע לתוקפים"],
