    id: "arch-014",
    category: "Architecture",
    topic: "Logging",
    difficulty: "intermediate",
    question: "למה חשוב להוסיף לוגים במערכת?",
    shortAnswer: "לוגים מאפשרים לאבחן בעיות, לעקוב אחר התנהגות, לזהות אנומליות ולהבין מה קרה כשמשהו השתבש.",
    simpleExplanation: "לוגים: תיעוד מה קרה, מתי, ובאיזה context — ה\"עדים\" של המערכת.\nLog levels: DEBUG / INFO / WARN / ERROR — לסנן לפי חומרה.\nמה לכלול: timestamp, level, request_id, service name, message מפורט.\nלא לכלול: סיסמאות, כרטיסי אשראי, PII — הלוגים נגישים להרבה אנשים.\nCentralized logging: ELK Stack / Splunk — ריכוז לוגים ממספר שרתים למקום אחד לחיפוש.",
    example: "שגיאה בפרודקשן → בלי לוגים: 'לא יודעים'. עם לוגים: 'user X ניסה לגשת ל-endpoint Y ב-13:42, DB החזיר null, הפונקציה Z נכשלה.'",
    whatToMention: ["Timestamp + level (info/warn/error)", "לא לשמור PII בלוגים", "מרכז לוגים (ELK, Splunk)"],
    commonMistakes: ["ללוג הכל — גורם לnoise. ללוג כלום — גורם לעיוורון"],
