    shortAnswer: "פרטיות — נתונים לא יוצאים לשרת חיצוני. מהירות — גישה מיידית בלי latency. עבודה offline — גם בלי אינטרנט.",
    simpleExplanation: "Local-First: נתונים נשמרים על מכשיר המשתמש, לא בשרת חיצוני.\nיתרונות: פרטיות (נתונים לא יוצאים), מהירות (ללא latency), offline (עובד ללא אינטרנט).\nWeb storage: localStorage (עד 5MB, string), IndexedDB (גדול, structured data).\nSync אופציונלי: Export/Import JSON — גיבוי בשליטת המשתמש, לא אוטומטי.\nRisk: מחיקת דפדפן/מכשיר = אובדן נתונים — גיבוי ידני חשוב.",
