    shortAnswer: "מתחילים מהפשוט ביותר שעונה על הצורך הנוכחי. מוסיפים מורכבות רק כשיש סיבה ממשית — לא מתוך ניחוש.",
    simpleExplanation: "Trade-off: כל בחירה ארכיטקטונית מביאה יתרון ועלות — אין פתרון מושלם.\nYAGNI (You Aren't Gonna Need It): לא לבנות לעתיד שלא הגיע — עלות ללא תועלת.\nPremature Optimization: לא לאופטמז לפני שמדדנו שיש בעיה.\nStart Simple: Monolith → Microservices. localStorage → IndexedDB. כשיש סיבה.\nהלל לפשטות: פתרון פשוט שעובד > פתרון מורכב שנבנה בגאווה.",
    example: "צריכים לשמור 10 הגדרות משתמש → localStorage מספיק. לא צריכים MongoDB.",
