    simpleExplanation: "Vertical Scaling (Scale Up): שדרוג שרת קיים — יותר CPU, RAM, SSD.\nHorizontal Scaling (Scale Out): הוספת שרתים זהים מאחורי load balancer.\nVertical: פשוט לביצוע, אבל יש גבול חומרה ו-single point of failure.\nHorizontal: גמיש יותר, אך דורש stateless services וsession ריכוזי.\nAuto Scaling: cloud מוסיף/מסיר instances אוטומטית לפי CPU/traffic.",
