    shortAnswer: "Load balancer מחלק בקשות נכנסות בין מספר שרתים כדי שאף אחד לא יהיה עמוס יותר מדי ושהמערכת תמשיך לעבוד גם אם שרת אחד נופל.",
    simpleExplanation: "Load Balancer: מחלק בקשות נכנסות בין מספר שרתים לפי אלגוריתם.\nאלגוריתמים: Round Robin (תורות), Least Connections (פחות עסוק), IP Hash (consistency).\nHealth Checks: load balancer שולח ping לכל שרת → מסיר שרת שלא עונה מהtore.\nLayer 4 vs Layer 7: L4 מחלק לפי TCP. L7 מחלק לפי URL/header — גמיש יותר.\nכלים: Nginx, HAProxy, AWS ALB/NLB, Cloudflare.",
