    shortAnswer: "רכיב שאם נופל — גורם לקריסת המערכת כולה. מטרה בתכנון טוב היא לאתר SPOFs ולבטל אותם דרך redundancy.",
    simpleExplanation: "SPOF: רכיב שאם נכשל — המערכת כולה מושבתת.\nדוגמאות: DB יחיד, load balancer יחיד, DNS server יחיד, API gateway יחיד.\nאיתור: לשרטט ארכיטקטורה ולשאול \"מה קורה אם רכיב זה נפל?\"\nפתרון: Redundancy — לפחות 2 instances לכל רכיב קריטי + failover אוטומטי.\nLoad Balancer כ-SPOF: גם ה-LB עצמו יכול להיות SPOF אם הוא יחיד.",
