    shortAnswer: "ארכיטקטורה שבה רכיבים מתקשרים על ידי פרסום ועדכון לאירועים, ולא דרך קריאות ישירות זה לזה.",
    simpleExplanation: "Event-Driven: רכיבים מתקשרים דרך events אסינכרוניים, לא קריאות ישירות זה לזה.\nProducer: מייצר event (\"order_placed\") ושולח ל-broker.\nConsumer: מקשיב ומטפל (\"send_email_service\", \"inventory_service\") — עצמאי.\nDecoupling: שירות X לא יודע מי קורא לו. שינוי consumer לא משפיע על producer.\nEvent Broker: Kafka (throughput גבוה), RabbitMQ (reliability), AWS SQS.",
