    question: "מה זה message queue ומתי משתמשים בו?",
    shortAnswer: "Message queue הוא תור שמאחסן הודעות בין שולח למקבל. מאפשר עיבוד אסינכרוני, decoupling ועמידות בעומסים.",
    simpleExplanation: "Message Queue: תור שבו producers כותבים הודעות ו-consumers קוראים בקצב שלהם.\nDecoupling: producer לא יודע מי עיבד — שניהם עצמאיים לגמרי.\nDurability: הודעות נשמרות גם אם consumer נפל — יעבד כשיחזור.\nPeak smoothing: spike בבקשות → queue סופג → consumers מעבדים בקצב קבוע.\nDead Letter Queue (DLQ): הודעות שנכשלו X פעמים עוברות ל-DLQ לבדיקה ידנית.",
