    id: "arch-adv-008",
    category: "Architecture",
    topic: "Cache Invalidation",
    difficulty: "advanced",
    question: "איך cache יכול לגרום לנתונים לא מעודכנים?",
    shortAnswer: "אם הנתון ב-DB השתנה אבל ה-cache לא עודכן, המערכת תמשיך להחזיר את הנתון הישן עד שה-cache יפוג (TTL) או יתרענן.",
    simpleExplanation: "Cache Invalidation: הגדרת מתי ואיך לנקות/לעדכן cache כשנתון ב-DB השתנה.\nTTL (Time To Live): cache תקף ל-X שניות — אחרי זה מתרענן אוטומטית.\nWrite-Through: מעדכן cache ו-DB יחד בכתיבה — תמיד עדכני, קצת איטי יותר.\nWrite-Invalidate: כתיבה → מנקה cache מיד → הבקשה הבאה תשלוף מ-DB ותאכלס.\nStale data: cache ישן שמחזיר נתונים לא עדכניים — Trade-off מול performance.",
    example: "מחיר מניה מcache: 100₪. DB עודכן ל-105₪. Cache TTL = 5 דקות. 5 דקות → לקוחות רואים מחיר לא נכון.",
    whatToMention: ["TTL (Time To Live) מגדיר כמה זמן cache תקף", "Cache invalidation = אחד הדברים הקשים", "Write-through vs Write-behind"],
    commonMistakes: ["TTL ארוך מדי לנתונים דינמיים", "לא לנקות cache כשמשהו משתנה"],
