    topic: "Microservices Trade-offs",
    difficulty: "advanced",
    question: "איך היית מסבירה למה לא תמיד נכון לבחור Microservices?",
    shortAnswer: "Microservices מוסיף מורכבות תפעולית גבוהה — networking, distributed tracing, service discovery, versioning. לצוות קטן או מוצר צעיר, Monolith עדיף.",
    simpleExplanation: "Microservices: גמישות גבוהה, scale לכל שירות בנפרד, team autonomy.\nאבל: service discovery, distributed tracing, inter-service auth, network latency.\nOperational overhead: כל שירות צריך CI/CD, monitoring, logging, alerting משלו.\nDebugging: בעיה ב-flow שחוצה 5 שירותים קשה לאבחן ללא distributed tracing.\nMonolith First: בנה monolith נקי → זיהוי צוואר הבקבוק → extract לשירות בעת הצורך.",
    example: "Startup של 3 מפתחים שבוחרת Microservices → מבלה 60% מהזמן על infra ולא על product. Monolith → 100% product.",
    whatToMention: ["Operational overhead גבוה", "Distributed debugging קשה", "'Monolith first' גישה מקובלת", "לעבור למicro כשיש כאב אמיתי"],
