    shortAnswer: "בשלות הטכנולוגיה, expertise בצוות, עלות תחזוקה, תאימות לstack קיים, ואם היא פותרת בעיה אמיתית ולא בעיה שלא קיימת.",
    simpleExplanation: "Maturity: כמה זמן הטכנולוגיה בשוק? יש production-proven use cases?\nTeam Expertise: האם מישהו בצוות מכיר? אחרת — learning curve + bugs.\nTCO (Total Cost of Ownership): לא רק פיתוח — תחזוקה, upgrades, onboarding עתידי.\nProblem-Solution Fit: האם פותר בעיה שיש לנו עכשיו? לא בעיה שאולי תהיה.\nExit Strategy: אם נרצה להחליף בעוד 2 שנים — כמה כואב? Vendor lock-in?",
