    shortAnswer: "Classification מנבא קטגוריה (ספאם/לא ספאם). Regression מנבא ערך מספרי רציף (מחיר דירה).",
    simpleExplanation: "Classification: ניבוי קטגוריה בדידה — ספאם/לא ספאם, כלב/חתול/ציפור.\nRegression: ניבוי ערך מספרי רציף — מחיר דירה, טמפרטורה מחר.\nBinary Classification: שתי קטגוריות (0/1). Multi-class: 3+ קטגוריות.\nמדדים שונים: Classification → Accuracy, F1. Regression → MAE, RMSE.\nהבדל בפלט: Classification → softmax/sigmoid. Regression → ערך ישיר.",
