    shortAnswer: "Accuracy הוא אחוז הניבויים הנכונים. הוא מטעה כשהדאטה לא מאוזן — מודל שתמיד מנבא 'לא חולה' יגיע ל-99% אם רק 1% חולים.",
    simpleExplanation: "Accuracy: אחוז הניבויים הנכונים מסך כל הניבויים.\nImbalanced data: אם 99% ממחלקה אחת, מודל שמנחש תמיד אותה = 99% accuracy ללא ערך.\nPrecision: מבין מה שסימנתי חיובי — כמה באמת חיובי. (TP/(TP+FP))\nRecall: מבין כל החיוביים האמיתיים — כמה זיהיתי. (TP/(TP+FN))\nתמיד לבדוק distribution: לפני שמעריכים accuracy, לבדוק כמה דוגמאות בכל class.",
