    category: "Machine Learning",
    topic: "Confusion Matrix",
    difficulty: "intermediate",
    question: "מה זו Confusion Matrix?",
    shortAnswer: "Confusion Matrix היא טבלה שמציגה כמה פעמים המודל ניבא נכון ושגוי לכל קטגוריה — TP, TN, FP, FN.",
    simpleExplanation: "Confusion Matrix: טבלה שמציגה 4 תוצאות אפשריות ב-binary classification.\nTP (True Positive): ניבאנו חיובי, הייתה חיובי — נכון.\nTN (True Negative): ניבאנו שלילי, הייתה שלילי — נכון.\nFP (False Positive): ניבאנו חיובי, הייתה שלילי — שגוי (Type I Error).\nFN (False Negative): ניבאנו שלילי, הייתה חיובי — שגוי (Type II Error — לרוב יקר יותר).",
    example: "זיהוי ספאם: TP=90 (זיהה ספאם נכון), FP=10 (סימן כשר כספאם), FN=5 (פספס ספאם), TN=895.",
    whatToMention: ["TP/TN/FP/FN", "בסיס לחישוב Precision ו-Recall", "עוזרת לזהות את סוג הטעויות"],
    commonMistakes: ["לחשב רק Accuracy מהmatrix ולא להסתכל על FP/FN בנפרד"],
    tags: ["confusion matrix", "evaluation", "classification"],
    source: "demo",
    createdAt: "2026-07-01",
    updatedAt: "2026-07-01",
