    shortAnswer: "בודקים ביצועים על test set עם מטריקות מתאימות לבעיה, ומשווים ל-baseline ול-ציפיות העסקיות.",
    simpleExplanation: "Evaluation: בדיקת ביצועי המודל על דאטה שלא ראה — הערכה אמינה.\nBaseline: תמיד להשוות — מה הציון של \"לנחש תמיד הרוב\"? המודל חייב לנצח.\nבחירת מטריקה: תלוי בבעיה — Imbalanced → F1/AUC. Medical → Recall.\nTrain/Val/Test: Train = ללמוד. Val = לכוונן. Test = לדווח — פעם אחת.\nBusiness context: accuracy טכנית לא מספיקה — מה ה-ROI העסקי של השיפור?",
