    simpleExplanation: "Algorithmic Bias: כשהמודל מוטה בצורה שיטתית כלפי קבוצה מסוימת.\nמקור: Bias בדאטה האימון — שיקוף של אפלייה היסטורית.\nזיהוי: בדיקת ביצועים לפי תת-קבוצות (מין, גיל, מוצא) — חיפוש פערים.\nDisparate Impact: קבוצה מוגנת מקבלת תוצאות שליליות בשיעור גבוה יותר.\nמניעה: דאטה מאוזן, Fairness constraints, בדיקות תת-קבוצה שגרתיות.",
