    topic: "Recall Priority",
    difficulty: "advanced",
    question: "מתי חשוב יותר Recall מאשר Precision?",
    shortAnswer: "כשעלות של False Negative (פספוס) גבוהה יותר מFalse Positive — למשל בזיהוי מחלות, גילוי הונאות, ניטור אבטחה.",
    simpleExplanation: "Recall Priority: כשהעלות של פספוס (FN) גבוהה מהעלות של אזעקת שווא (FP).\nזיהוי מחלה: עדיף לשלוח 100 לבדיקה (FP) מלפספס חולה אחד (FN).\nזיהוי הונאות: עדיף לחסום עסקה תקינה (FP) מלאפשר הונאה (FN).\nניטור אבטחה: עדיף alert שקרי (FP) מפספוס פריצה (FN).\nפרקטית: להוריד threshold → Recall עולה, Precision יורדת. לאזן לפי עלויות.",
