    shortAnswer: "חלוקת הדאטה לk חלקים, אימון ובדיקה k פעמים — כל פעם חלק אחר כtest. ממוצע התוצאות נותן הערכה אמינה יותר.",
    simpleExplanation: "K-Fold CV: מחלקים דאטה ל-k חלקים. k-1 לאימון, 1 לvalidation. חוזרים k פעמים.\nיתרון: מנצל כל הדאטה להערכה, הרבה יותר אמין מ-single split.\nk=5 או k=10 נפוצים. k גדול = הערכה טובה יותר אבל חישוב איטי יותר.\nStratified K-Fold: שומרת על יחס classes בכל fold — חשוב ב-imbalanced data.\nTime Series: חייב להיות forward-looking — לא לערבב עבר ועתיד.",
    example: "5-Fold CV: מחלקים ל-5. מאמנים על 4, בודקים על 1. חוזרים 5 פעמים ומממוצעים תוצאות.",
    whatToMention: ["אמין יותר מ-single train/test split", "k=5 או k=10 נפוץ", "LOOCV = k=n (כל דוגמה כ-test)"],
