    question: "מה הסיכון בשימוש במודל שלא עודכן הרבה זמן?",
    shortAnswer: "הדאטה בעולם האמיתי משתנה לאורך זמן (Data Drift). מודל ישן יכול לתת תחזיות לא מדויקות כי הדפוסים שלמד כבר לא תקפים.",
    simpleExplanation: "Data Drift: התפלגות הדאטה הנכנס משתנה לאורך זמן — מודל שאומן לפני לא תקף.\nConcept Drift: הקשר בין features ל-label משתנה — דפוסי ביקוש, מחירים, התנהגות.\nניטור: מדידת ביצועים שוטפת בproduction. PSI ו-KL Divergence לגילוי drift.\nRetraining: תזמון עדכון מודל — לפי לוח זמנים קבוע או לפי alert של drift.\nCanary Deployment: מפרסים גרסה חדשה על תנועה קטנה → משווים → מרחיבים.",
    example: "מודל חיזוי ביקוש שאומן לפני COVID ימשיך לנבא דפוסי ביקוש ישנים — לא יתאים לשינויי הצריכה.",
