    topic: "Fairness",
    difficulty: "advanced",
    question: "איך היית בודקת אם מודל מתנהג בצורה לא הוגנת כלפי קבוצה מסוימת?",
    shortAnswer: "לבדוק מטריקות ביצועים (Accuracy, Recall, FP rate) בנפרד לפי קבוצות — מין, גיל, מוצא — ולחפש פערים משמעותיים.",
    simpleExplanation: "Algorithmic Fairness: בדיקה שהמודל לא מפלה קבוצות מוגנות.\nבדיקה: ביצועים (Accuracy, Recall, FP rate) לפי תת-קבוצות — גיל, מין, מוצא.\nDisparate Impact: קבוצה מוגנת מקבלת תוצאות שליליות ב-80%+ מאחרות → flag.\nEqualized Odds: FP rate ו-FN rate שווים בין קבוצות — fairness metric.\nאתיקה ועמידה בחוק: GDPR, AI Act מחייבים בדיקת fairness בהחלטות אוטומטיות.",
    example: "מודל גיוס: Recall לנשים=60%, לגברים=90% → המודל מפספס נשים מוכשרות → הטיה.",
    whatToMention: ["Disparate Impact", "ביצועים לפי תת-קבוצות", "Fairness metrics כמו Equalized Odds"],
    commonMistakes: ["להניח שמודל הוא אוטומטית הוגן כי הוא אלגוריתמי"],
