    shortAnswer: "המודל מנבא, משווה לתשובה הנכונה, מחשב שגיאה (Loss), ועדכן משקולות לכיוון שמפחית את השגיאה — שוב ושוב.",
    simpleExplanation: "Forward Pass: הדאטה עובר קדימה בשכבות → יוצא חיזוי.\nLoss Computation: השוואת חיזוי לתשובה נכונה → Loss (ציון שגיאה).\nBackpropagation: מחשב gradient — כמה כל משקולת תרמה לשגיאה.\nWeight Update: מעדכן משקולות לכיוון שמפחית Loss (Gradient Descent).\nחזרה על הלולאה: מאות אלפי פעמים עד שLoss מתכנס.",
