    question: "איך Overfitting יכול לקרות גם ברשת נוירונים?",
    shortAnswer: "רשת גדולה עם דאטה קטן תשנן את דוגמאות האימון. פתרונות: Dropout, Weight Decay, Data Augmentation, Early Stopping.",
    simpleExplanation: "Overfitting ב-DL: רשת גדולה על דאטה קטן תשנן כל דוגמה, לא תלמד דפוס.\nDropout: מכבה נוירונים רנדומלית בזמן אימון — מונע co-adaptation, מכריח הכללה.\nEarly Stopping: עוצר כשVal Loss מפסיק להשתפר — שמירת המשקולות הטובות.\nData Augmentation: הוספת גרסאות מוגדלות, מסובבות, חתוכות של תמונות — מגדיל דאטה בפועל.\nWeight Decay (L2 Regularization): מוסיף penalty על משקולות גדולות.",
