    id: "dl-adv-002",
    category: "Deep Learning",
    topic: "Gradient Descent",
    difficulty: "advanced",
    question: "מה זה Gradient Descent במילים פשוטות?",
    shortAnswer: "אלגוריתם אופטימיזציה שמחשב לכל משקולת לאיזה כיוון לזוז כדי להפחית את ה-Loss — זזים צעד קטן בכיוון ה'מורד'.",
    simpleExplanation: "Gradient Descent: מוצאים כיוון שמוריד את ה-Loss זזים הפוך מה-Gradient בגודל ה-Learning Rate.\nLearning Rate (α): קטן מדי = אימון ארוך, גדול מדי = קפיצה מעל המינימום ואי-התכנסות.\nSGD (Stochastic): Gradient על דוגמה אחת — מהיר אבל עם רעש. Batch GD: על כל הדאטה — יציב אבל איטי.\nMini-batch: סט קטן של דוגמאות — האיזון הנפוץ ביותר בפועל (batch_size=32/64/128).\nAdam Optimizer: מסתגל ל-Learning Rate אוטומטית לכל פרמטר — ברירת המחדל ברוב הפרויקטים.",
    example: "Learning rate = גודל הצעד. גדול מדי → קופצים מעל המינימום. קטן מדי → לוקח עד עולם לרדת.",
    whatToMention: ["Gradient = כיוון ה'עלייה'", "GD = זזים נגד הגradient", "SGD, Adam הם וריאנטים"],
    commonMistakes: ["Learning rate גדול מדי → loss מתנדנד ולא מתכנס"],
    tags: ["gradient descent", "optimization", "learning rate", "deep learning"],
