    simpleExplanation: "פרמטרים vs דאטה: מודל עם 175B פרמטרים 'מחפש' לאמוד 175B מספרים — צריך מספיק דוגמאות להגדיר אותם.\nOverfitting: מעט דאטה + מודל גדול = שינון. המודל לומד את הדוגמאות עצמן, לא את הדפוס הכללי.\nData Augmentation: הגדלה מלאכותית של דאטה — סיבובים, מריחות, אוגמנטציה — 'מרמה' את המודל.\nSelf-Supervised Learning: GPT אומן לנבא מילה הבאה — הדאטה עצמו הוא התווית, לא צריך annotation.\nScaling Laws: Chinchilla paper: מודל אופטימלי = מספר פרמטרים ≈ 20× גודל דאטה בטוקנים.",
