    question: "מה זה Prompt?",
    shortAnswer: "Prompt הוא ההוראה/השאלה שאנחנו שולחים למודל AI. איכות ה-Prompt משפיעה מאוד על איכות התשובה.",
    simpleExplanation: "Prompt: הקלט שנותנים ל-LLM — שאלה, הוראה, הקשר, דוגמאות או כל שילוב.\nSystem Prompt: הוראות לMודל לפני השיחה — מגדיר אישיות, שפה, פורמט, מגבלות.\nUser Prompt: מה המשתמש שולח בפועל בזמן השיחה.\nFew-shot: כלול דוגמאות של שאלה-תשובה ב-Prompt — מראה למודל מה מצפים.\nPrompt Engineering: אמנות/מדע של כתיבת Prompts יעילים — ספציפיות, הקשר, פורמט רצוי, מגבלות.",
    example: "Prompt רע: 'כתוב קוד'. Prompt טוב: 'כתוב פונקציה Python שמקבלת רשימת מספרים ומחזירה ממוצע, עם type hints.'",
