    shortAnswer: "LLM (Large Language Model) הוא מודל Transformer שאומן על כמויות ענק של טקסט ויכול להבין ולייצר שפה טבעית.",
    simpleExplanation: "LLM (Large Language Model): מודל Transformer עם מיליארדי פרמטרים, אומן על כמויות עצומות של טקסט.\nאימון: Self-supervised — ניבוי token הבא ב-95% מהאימון (GPT), הבנת הקשר (BERT) ועוד.\nגודל: GPT-3 = 175B פרמטרים, 570GB טקסט. GPT-4 ≈ כמה טריליון פרמטרים (לא אושר רשמית).\nיכולות: שיחה, תרגום, קוד, סיכום, ניתוח, מענה לשאלות — מתוך דפוסים שלמד.\nלא 'יודע': מנבא טקסט סביר מסטטיסטיקה — לא מבין, לא זוכר, לא בטוח בעצמו אוטומטית.",
