    shortAnswer: "המשתמש שולח הודעה, ה-LLM מקבל את ההיסטוריה + ההודעה כprompt, מחשב את המשך הסביר ביותר ומחזיר תגובה.",
    simpleExplanation: "זרימה: User שולח הודעה → Backend מוסיף System Prompt + היסטוריה → LLM מחשב → מחזיר תגובה.\nהיסטוריה: כל שיחה = prompt שגדל עם כל הודעה — הLLM לא 'זוכר', הכל נשלח מחדש.\nContext Window: יש גבול לכמות הטקסט. שיחה ארוכה → מידע ישן נשמט.\nSystem Prompt: הוראות קבועות ל-AI — אישיות, שפה, מגבלות. נשמר ב-backend.\nStreaming: LLM מחזיר token אחר token — לכן נראה כאילו 'מקליד' בזמן אמת.",
