    question: "מה זה RAG במילים פשוטות?",
    shortAnswer: "RAG (Retrieval-Augmented Generation) הוא שיטה שמחפשת מסמכים רלוונטיים ומוסיפה אותם לprompt לפני שהLLM עונה — מפחית hallucinations.",
    simpleExplanation: "בעיית LLM: ידע קפוא בזמן האימון — לא יודע עובדות חדשות, עלול לhallucinate.\nRAG פתרון: שאלה נכנסת → חיפוש מסמכים רלוונטיים ב-DB → מוסיפים ל-Prompt → LLM עונה לפי המסמכים.\nVector DB: מחפשים מסמכים לפי דמיון סמנטי — לא keyword matching אלא Embedding similarity.\nיתרון: מידע עדכני, ניתן לאימות, מקטין hallucinations, מאפשר ציטוט מקורות.\nמגבלה: איכות תלויה באיכות הretrieval — מסמך שגוי = תשובה שגויה.",
