    shortAnswer: "Prompt engineering = שינוי הקלט למודל קיים. Fine-tuning = אימון המודל על דאטה חדש לשנות את התנהגותו.",
    simpleExplanation: "Prompt Engineering: שינוי הקלט למודל קיים — מהיר, זול, לא דורש GPUs, ניתן לשנות בכל רגע.\nFine-tuning: אימון נוסף על דאטה ספציפי — משנה פרמטרים, יקר, GPUs נדרשים, תוצאה קבועה.\nמתי Prompt: שינוי אישיות, שפה, פורמט, הוספת הוראות — Prompt Engineering ראשון תמיד.\nמתי Fine-tune: סגנון מאוד ספציפי שלא מגיע מprompt, דומיין נישה שLLM לא אימן עליו.\nRAG כחלופה: לידע עובדתי ספציפי — RAG לרוב עדיף על fine-tuning כי גמיש ועדכני.",
