    difficulty: "advanced",
    question: "מה זה context window?",
    shortAnswer: "Context window הוא כמות הטקסט שהLLM יכול 'לראות' בבת אחת — prompt + היסטוריה + תשובה. מידע מחוץ לcredit window נשכח.",
    simpleExplanation: "Context Window: סך הטוקנים שהLLM יכול לעבד בבת אחת — System Prompt + שיחה + מסמכים + תשובה.\nגדלים: GPT-4 = 128K tokens ≈ 90K מילים. Claude 3 = 200K tokens. Gemini = 1M tokens.\nתוצאת חריגה: LLM מתחיל לשכוח את תחילת השיחה/מסמך — בדרך כלל מה שנמצא באמצע.\nLost in the Middle: מחקר מצא שLLMs זוכרים טוב יותר תחילת וסוף context, פחות את האמצע.\nRational management: RAG מחזיר רק המסמכים הרלוונטיים במקום לטעון הכל — מנצל Context בצורה חכמה.",
    example: "GPT-4 Turbo: 128K tokens ≈ ~90,000 מילים. שיחה ארוכה מגיעה לגבול → המודל שוכח את תחילת השיחה.",
    whatToMention: ["גבול לכמות הטקסט", "שיחות ארוכות יאבדו מידע ישן", "RAG עוזר לנהל מידע מחוץ לחלון"],
    commonMistakes: ["לחשוב שLLM זוכר את כל השיחות הקודמות — הוא לא"],
