    simpleExplanation: "Lost in the Middle: LLM מתמקד בתחילת וסוף context — מידע באמצע עלול להיות מוחמץ.\nNoise Dilution: מידע לא רלוונטי 'מדלל' את הסיגנל — המודל מסיח דעת לפרטים לא חשובים.\nConflicting Information: מסמכים סותרים ב-context → המודל מתקשה לבחור — תשובה לא עקבית.\nLatency ועלות: יותר tokens = יותר זמן חישוב ועלות גבוהה יותר ב-API.\nפתרון: Retrieval מדויק — 3-5 מסמכים רלוונטיים עדיפים על 20 מסמכים כלליים.",
