    id: "ai-adv-004",
    category: "AI",
    topic: "Grounding",
    difficulty: "advanced",
    question: "מה זה grounding בתשובות AI?",
    shortAnswer: "Grounding הוא עיגון תשובות AI במקורות אמינים וניתנים לאימות — כך ניתן לאמת טענות ולהפחית hallucinations.",
    simpleExplanation: "Grounding: קישור תשובות ה-AI למקורות ספציפיים וניתנים לאימות — לא 'אמירות מהאוויר'.\nRAG כ-Grounding: מסמכים שנכנסו ל-Context = הבסיס לתשובה. LLM אמור לאחז אותם.\nCitations: LLM עם Grounding מסוגל לצרף '[מסמך X, עמוד Y]' לכל טענה.\nסיכון: LLM עדיין יכול לbדות citations — לכתוב ציטוט שנראה נכון אבל לא מופיע במקור.\nבדיקה: לאמת כל citation ידנית לפחות בשלב הפיתוח — לא להניח שcitation = נכון.",
    example: "LLM עם grounding: 'לפי מסמך X, סעיף 3: ...' ומצרף לינק. ניתן לבדוק. בלי grounding: תשובה עובדתית שאי אפשר לאמת.",
    whatToMention: ["מקורות לאימות", "RAG הוא דרך לgrounding", "Citations ו-attribution", "מפחית hallucinations"],
