    shortAnswer: "RAG מוסיף מידע דינמי בזמן שאילתה. Fine-tuning/Retraining משנה את הפרמטרים של המודל — קבוע ויקר הרבה יותר.",
    simpleExplanation: "RAG: מוסיף מידע חיצוני בזמן שאילתה — המודל עצמו לא משתנה. גמיש, מתעדכן, זול יחסית.\nFine-tuning: משנה פרמטרי המודל על דאטה חדש — יקר, לוקח זמן, תוצאה קבועה עד אימון הבא.\nRetraining: אימון מחדש מאפס או מ-checkpoint — הכי יקר, לשינויים ארכיטקטורליים.\nכלל אצבע: דאטה עדכני שמשתנה → RAG. סגנון/מיומנות ספציפית שLLM לא שולט → Fine-tune.\nLRAG: חיבור RAG + Fine-tune — המודל אומן להשתמש ב-RAG בצורה מיטבית.",
    example: "מידע עדכני חדשותי → RAG (מסמכים מתעדכנים). סגנון תקשורת ספציפי → Fine-tuning (יקר, חד-פעמי).",
